def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    access_order = []  # list of keys in order of access
    results = []

    def is_expired(key, current_time):
        if key not in cache:
            return True
        _, write_time = cache[key]
        return current_time >= write_time + ttl

    def mark_accessed(key):
        # Move key to the end of access_order (most recently used)
        if key in access_order:
            access_order.remove(key)
        access_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Check if we need to evict
            if key not in cache and len(cache) >= capacity:
                # Remove least recently used entry
                lru_key = access_order.pop(0)
                del cache[lru_key]

            # Store the value
            cache[key] = (value, t)
            mark_accessed(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache and not is_expired(key, t):
                value, _ = cache[key]
                results.append(value)
                mark_accessed(key)
            else:
                results.append(-1)

    return results

